import assert from "node:assert/strict";
import { Engine, memoryStore } from "../static/engine.mjs";
import * as wire from "../static/wire.mjs";
const store=memoryStore(), e=new Engine({store,base:"https://example.test"});
e.me={person:wire.newID()};e.address="owner/phone";
const n={seq:1,id:wire.newID(),person:e.me.person,device:"owner/pixel",by:"owner/laptop",admin:true,at:1791214800};
await e.dispatch("device_admin",JSON.stringify(n));
await e.dispatch("device_admin",JSON.stringify(n));
let notices=await e.deviceAdminReview();assert.equal(notices.length,1);
assert.equal(notices[0].reason,"device_admin");assert.equal(notices[0].notice,true);
assert.match(notices[0].why,/^Your Pixel can now change company settings — granted from Laptop at \d\d:\d\d\.$/);
assert(!notices[0].why.includes("owner/"));
await e.dispatch("device_admin",JSON.stringify({...n,id:wire.newID(),person:wire.newID()}));
assert.equal((await e.deviceAdminReview()).length,1,"foreign person excluded");
await e.api("/api/act",{do:"resolve",id:n.id});
const again=new Engine({store,base:"https://example.test"});again.me=e.me;
await again.dispatch("device_admin",JSON.stringify(n));
assert.equal((await again.deviceAdminReview()).length,0,"reconnect does not restore dismissed note");
await again.dispatch("device_admin",JSON.stringify({...n,id:wire.newID(),seq:2,admin:false}));
assert.match((await again.deviceAdminReview())[0].why,/can no longer change company settings — withdrawn from Laptop/);
assert.equal((await store.all("inbox")).length,0);assert.equal((await store.all("outbox")).length,0);
console.log("device admin notice persistence, privacy, naming, dismissal PASS");
